import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Full archive isolation and preservation of the original BATTLE gate/receiver classes. */
public final class CompanionProcSceneDelta {
 static final String P="local/lito381/server/",C=P+"NativeProcHealingCompanion.class";
 static ClassNode read(JarFile j,String name)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(name))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static byte[] method(ClassNode c,MethodNode m,String name){var copy=new MethodNode(m.access,name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(copy);var q=new ClassNode();q.version=c.version;q.access=c.access;q.name=c.name;q.superName=c.superName;q.methods.add(copy);var w=new ClassWriter(0);q.accept(w);return w.toByteArray();}
 public static void main(String[]args)throws Exception{try(var before=new JarFile(args[0]);var after=new JarFile(args[1])){
  var names=new HashSet<String>();var changed=new TreeSet<String>();for(var e:Collections.list(before.entries())){names.add(e.getName());var n=after.getJarEntry(e.getName());if(n==null)throw new AssertionError("removed "+e.getName());if(!Arrays.equals(before.getInputStream(e).readAllBytes(),after.getInputStream(n).readAllBytes()))changed.add(e.getName());}
  var fresh=new TreeSet<String>();for(var e:Collections.list(after.entries()))if(!names.contains(e.getName()))fresh.add(e.getName());if(!changed.equals(Set.of(C))||!fresh.equals(Set.of(P+"NativeCompanionProcScene.class")))throw new AssertionError("archive delta "+changed+" "+fresh);
  var b=read(before,C);var a=read(after,C);if(b.fields.size()!=a.fields.size())throw new AssertionError("new original field");for(int i=0;i<b.fields.size();i++){var x=b.fields.get(i);var y=a.fields.get(i);if(!x.name.equals(y.name)||!x.desc.equals(y.desc)||x.access!=y.access||!Objects.equals(x.value,y.value))throw new AssertionError("original fields changed");}
  for(var m:b.methods){if(m.name.equals("publish"))continue;String expected=m.name.equals("withTarget")?"nativeProcSceneOriginalWithTarget":m.name;var q=a.methods.stream().filter(v->v.name.equals(expected)&&v.desc.equals(m.desc)).findFirst().orElseThrow();if(!Arrays.equals(method(b,m,m.name),method(a,q,m.name)))throw new AssertionError("original method changed "+m.name+m.desc);}
  var h=read(after,P+"NativeCompanionProcScene.class");if(!h.fields.isEmpty())throw new AssertionError("helper must be stateless");int emissions=0;for(var m:h.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==Opcodes.NEW&&!Set.of("java/lang/IllegalStateException","java/lang/RuntimeException","java/lang/ref/WeakReference").contains(t.desc))throw new AssertionError("new retained/execution owner "+t.desc);if(n instanceof MethodInsnNode v&&(v.owner.startsWith("java/sql/")||v.owner.startsWith("javax/sql/")||v.owner.startsWith("java/nio/file/")||v.owner.contains("AccountRepository")||v.owner.endsWith("GameStateStore")||v.name.equals("nativeDeInventory")))throw new AssertionError("new SQL/file/inventory dependency");if(n instanceof MethodInsnNode v&&v.name.equals("nativeSelfOriginalSend")){if(!m.name.startsWith("lambda$sendMeter$"))throw new AssertionError("unscoped output");for(var type:Type.getArgumentTypes(m.desc))if(Set.of("L"+P+"ClientSession;","L"+P+"GameHub;","L"+P+"BattleCompanion;","L"+P+"NativeProcHealingCompanion$Live;").contains(type.getDescriptor()))throw new AssertionError("deferred output captures strong owner/hub/actor/live");emissions++;}}if(emissions!=1)throw new AssertionError("one weak/value guarded emitter");
  for(var name:List.of("ClientSession","NativeCombatAttacker","NativeCombatAttacker$Ref","NativeCompanionRefScene","NativePlayerCommit","NativePlayerCommit$Binding","NativePlayerLifetime","NativeNpcLifetime","NativePairedCastSafety","NativeProcHealingKernel","NativeProcHealingCompanion$Plan","NativeProcHealingCompanion$Live","NativeProcHealingCompanion$Dispatch","NativeProcHealingCompanion$Meter","NativeProcHealingCompanion$Receipt")){var n=P+name+".class";if(!Arrays.equals(before.getInputStream(before.getJarEntry(n)).readAllBytes(),after.getInputStream(after.getJarEntry(n)).readAllBytes()))throw new AssertionError("shared/receiver contract changed "+name);}
 }System.out.println("PASS one changed/one stateless fresh class; original BATTLE withTarget body and all other methods except scoped publish unchanged; no new fields/workers/clock/TLS/registry/SQL/file/player-inventory dependency");}
}
